var App={};
function generateId(){return 'id_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7);}
function createEngineer(name,timezoneOffset,role){
 if(!name||!name.trim())throw new Error('Name required');
 if(typeof timezoneOffset!=='number'||timezoneOffset<-12||timezoneOffset>14)throw new Error('Invalid timezone offset');
 if(timezoneOffset*2!==Math.round(timezoneOffset*2))throw new Error('Offset must be 0.5 increments');
 var off=timezoneOffset;
 var label=off>=0?'UTC+'+off:'UTC'+off;
 return{id:generateId(),name:name.trim(),timezoneOffset:off,timezoneLabel:label,role:role||'',shiftCount:0,totalHours:0};
}
function createTeam(name){return{id:generateId(),name:name||'Team',engineers:[],incidents:[],schedule:[]};}
function addEngineer(team,engineerData){
 if(!team)throw new Error('Team required');
 var eng;
 if(engineerData.id&&engineerData.timezoneOffset!==undefined) eng=engineerData;
 else eng=createEngineer(engineerData.name,engineerData.timezoneOffset,engineerData.role);
 team.engineers.push(eng);
 return team;
}
function removeEngineer(team,engineerId){
 team.engineers=team.engineers.filter(function(e){return e.id!==engineerId;});
 team.schedule.forEach(function(s){if(s.engineerId===engineerId){s.engineerId=null;s.engineerName='Unassigned';}});
 return team;
}
function convertToLocalTime(utcISO,offsetHours){
 var d=new Date(utcISO);
 if(isNaN(d.getTime()))throw new Error('Invalid date');
 return new Date(d.getTime()+offsetHours*3600000).toISOString();
}
function getHandoffDisplay(shift){
 function fmt(iso){var d=new Date(iso);return String(d.getUTCHours()).padStart(2,'0')+':'+String(d.getUTCMinutes()).padStart(2,'0');}
 var engLabel='';
 if(shift.timezoneLabel) engLabel=' ('+shift.timezoneLabel+')';
 else if(shift.timezoneOffset!==undefined){var o=shift.timezoneOffset;engLabel=' (UTC'+(o>=0?'+'+o:o)+')';}
 return 'UTC '+fmt(shift.startUTC)+' \u2192 Local '+fmt(shift.localStart)+engLabel;
}
function generateSchedule(team,startDateISO,days,options){
 if(!team||!team.engineers.length)throw new Error('Team must have at least 1 engineer');
 if(!startDateISO||isNaN(new Date(startDateISO).getTime()))throw new Error('Invalid start date');
 if(typeof days!=='number'||days<1||days>60)throw new Error('Days must be 1-60');
 var dur=(options&&options.shiftDurationHours)||12;
 if([8,12,24].indexOf(dur)===-1)throw new Error('Invalid shift duration');
 var shiftsPerDay=Math.floor(24/dur);
 var totalShifts=days*shiftsPerDay;
 var start=new Date(startDateISO);
 var hoursMap={};
 team.engineers.forEach(function(e){hoursMap[e.id]=0;});
 var schedule=[];
 for(var i=0;i<totalShifts;i++){
  var sUTC=new Date(start.getTime()+i*dur*3600000);
  var eUTC=new Date(sUTC.getTime()+dur*3600000);
  var sorted=team.engineers.slice().sort(function(a,b){return hoursMap[a.id]-hoursMap[b.id];});
  var eng=sorted[0];
  hoursMap[eng.id]+=dur;
  var localStart=convertToLocalTime(sUTC.toISOString(),eng.timezoneOffset);
  var localEnd=convertToLocalTime(eUTC.toISOString(),eng.timezoneOffset);
  var day=sUTC.getUTCDay();
  var hr=sUTC.getUTCHours();
  schedule.push({
   id:generateId(),date:sUTC.toISOString().slice(0,10),startUTC:sUTC.toISOString(),endUTC:eUTC.toISOString(),
   engineerId:eng.id,engineerName:eng.name,localStart:localStart,localEnd:localEnd,
   durationHours:dur,timezoneOffset:eng.timezoneOffset,timezoneLabel:eng.timezoneLabel,
   isNight:hr>=22||hr<6,isWeekend:day===0||day===6
  });
 }
 schedule.sort(function(a,b){return new Date(a.startUTC)-new Date(b.startUTC);});
 team.schedule=schedule;
 team.engineers.forEach(function(e){e.totalHours=hoursMap[e.id];e.shiftCount=schedule.filter(function(s){return s.engineerId===e.id;}).length;});
 return schedule;
}
function validateSchedule(schedule){
 var gaps=[],overlaps=[];
 var sorted=schedule.slice().sort(function(a,b){return new Date(a.startUTC)-new Date(b.startUTC);});
 for(var i=1;i<sorted.length;i++){
  var prev=new Date(sorted[i-1].endUTC).getTime();
  var cur=new Date(sorted[i].startUTC).getTime();
  if(cur>prev) gaps.push({index:i,from:sorted[i-1].endUTC,to:sorted[i].startUTC});
  if(cur<prev) overlaps.push({index:i,a:sorted[i-1].id,b:sorted[i].id});
 }
 return{valid:gaps.length===0&&overlaps.length===0,gaps:gaps,overlaps:overlaps};
}
function exportScheduleCSV(schedule){
 var h='Date,StartUTC,EndUTC,Engineer,DurationHours,LocalStart';
 var rows=schedule.map(function(s){return [s.date,s.startUTC,s.endUTC,s.engineerName,s.durationHours,s.localStart].join(',');});
 return [h].concat(rows).join('\n');
}
function calculateEngineerLoad(team,engineerId){
 var shifts=team.schedule.filter(function(s){return s.engineerId===engineerId;});
 var totalHours=shifts.reduce(function(a,s){return a+s.durationHours;},0);
 var incs=team.incidents.filter(function(x){return x.engineerId===engineerId;});
 var incidentLoad=incs.reduce(function(a,x){return a+(x.fatiguePoints||0);},0);
 return{shiftCount:shifts.length,totalHours:totalHours,incidentCount:incs.length,incidentLoad:incidentLoad,totalLoad:totalHours+incidentLoad};
}
function calculateFairnessIndex(team){
 var n=team.engineers.length;
 if(n===0) return 1;
 var loads=team.engineers.map(function(e){return calculateEngineerLoad(team,e.id).totalLoad;});
 var sum=loads.reduce(function(a,b){return a+b;},0);
 if(sum===0) return 1;
 var sumSq=loads.reduce(function(a,b){return a+b*b;},0);
 if(sumSq===0) return 1;
 var j=(sum*sum)/(n*sumSq);
 return Math.max(0,Math.min(1,j));
}
function maxStreak(schedule,engineerId){
 var sorted=schedule.slice().sort(function(a,b){return new Date(a.startUTC)-new Date(b.startUTC);});
 var max=0,cur=0;
 sorted.forEach(function(s){if(s.engineerId===engineerId){cur++;if(cur>max)max=cur;}else cur=0;});
 return max;
}
function calculateFatigueScore(team,engineerId){
 var shifts=team.schedule.filter(function(s){return s.engineerId===engineerId;});
 var night=shifts.filter(function(s){return s.isNight;}).length;
 var weekend=shifts.filter(function(s){return s.isWeekend;}).length;
 var streak=maxStreak(team.schedule,engineerId);
 var incs=team.incidents.filter(function(x){return x.engineerId===engineerId;});
 var sevSum=incs.reduce(function(a,x){return a+x.severity;},0);
 var raw=night*1.5+weekend*1.2+streak*2+sevSum*3;
 return Math.min(100,Math.round(raw*2));
}
function getFatigueReport(team){
 return team.engineers.map(function(e){
  var score=calculateFatigueScore(team,e.id);
  var level=score<40?'healthy':score<65?'watch':score<80?'fatigued':'critical';
  return{engineerId:e.id,engineerName:e.name,fatigueScore:score,level:level};
 });
}
function logIncident(team,data){
 if(!data.engineerId)throw new Error('engineerId required');
 if(typeof data.severity!=='number'||data.severity<1||data.severity>5)throw new Error('Severity 1-5');
 if(!data.timestampUTC||isNaN(new Date(data.timestampUTC).getTime()))throw new Error('Invalid timestamp');
 var dur=data.durationMinutes||0;
 var fp=data.severity*(1+dur/60);
 var inc={id:generateId(),engineerId:data.engineerId,timestampUTC:new Date(data.timestampUTC).toISOString(),severity:data.severity,durationMinutes:dur,description:data.description||'',fatiguePoints:fp};
 team.incidents.push(inc);
 return inc;
}
function autoRebalance(team){
 var report=getFatigueReport(team);
 var maxF=Math.max.apply(null,report.map(function(r){return r.fatigueScore;}));
 if(maxF<=65) return{swaps:[],oldFairness:calculateFairnessIndex(team),newFairness:calculateFairnessIndex(team),reason:'No rebalance needed'};
 var oldFairness=calculateFairnessIndex(team);
 var sorted=report.slice().sort(function(a,b){return b.fatigueScore-a.fatigueScore;});
 var most=sorted[0],least=sorted[sorted.length-1];
 var upcoming=team.schedule.slice().sort(function(a,b){return new Date(a.startUTC)-new Date(b.startUTC);});
 var swaps=[];
 var count=0;
 for(var i=0;i<upcoming.length&&count<2;i++){
  if(upcoming[i].engineerId===most.engineerId){
   var leastEng=team.engineers.find(function(e){return e.id===least.engineerId;});
   swaps.push({from:most.engineerId,to:least.engineerId,shiftId:upcoming[i].id});
   upcoming[i].engineerId=least.engineerId;
   upcoming[i].engineerName=least.engineerName;
   if(leastEng){upcoming[i].timezoneOffset=leastEng.timezoneOffset;upcoming[i].timezoneLabel=leastEng.timezoneLabel;upcoming[i].localStart=convertToLocalTime(upcoming[i].startUTC,leastEng.timezoneOffset);upcoming[i].localEnd=convertToLocalTime(upcoming[i].endUTC,leastEng.timezoneOffset);}
   count++;
  }
 }
 var newFairness=calculateFairnessIndex(team);
 return{swaps:swaps,oldFairness:oldFairness,newFairness:newFairness,reason:'Swapped '+swaps.length+' shifts from '+most.engineerName+' to '+least.engineerName};
}
App.generateId=generateId;App.createEngineer=createEngineer;App.createTeam=createTeam;App.addEngineer=addEngineer;App.removeEngineer=removeEngineer;App.convertToLocalTime=convertToLocalTime;App.generateSchedule=generateSchedule;App.getHandoffDisplay=getHandoffDisplay;App.validateSchedule=validateSchedule;App.exportScheduleCSV=exportScheduleCSV;App.calculateEngineerLoad=calculateEngineerLoad;App.calculateFairnessIndex=calculateFairnessIndex;App.calculateFatigueScore=calculateFatigueScore;App.getFatigueReport=getFatigueReport;App.logIncident=logIncident;App.autoRebalance=autoRebalance;
if(typeof module!=='undefined'&&module.exports) module.exports=App;
if(typeof globalThis!=='undefined') globalThis.AppCore=App;
if(typeof window!=='undefined') window.OnCallApp=App;

// Isomorphic facade — Node require('./domain.js') and browser global OnCallDomain.
(function (root) {
  const domain = (typeof module !== 'undefined' && module.exports)
    ? require('./domain.js')
    : root.OnCallDomain;
  const api = { timezoneOffsetHours: domain.timezoneOffsetHours, localHour: domain.localHour, jainIndex: domain.jainIndex, OnCallScheduler: domain.OnCallScheduler };
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = api;
  }
  if (typeof globalThis !== 'undefined') {
    globalThis.AppCore = api;
  } else if (root) {
    root.AppCore = api;
  }
